// Mirror package.json's version into the iOS project. iOS reads MARKETING_VERSION
// from ios/version.xcconfig, which this script generates, so the version is edited
// in exactly one place. package.json's build script runs it; --check reports a
// stale file instead of writing it.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = fileURLToPath(new URL('..', import.meta.url))
const TARGET = join(ROOT, 'ios', 'version.xcconfig')
const HEADER = [
  '// Generated by scripts/sync-version.mjs from package.json.',
  '// Do not edit: MARKETING_VERSION is package.json\'s version, mirrored here for the',
  '// iOS bundle (CFBundleShortVersionString). Change package.json and run pnpm build,',
  '// or pnpm sync:version on its own.'
]

const fail = message => {
  console.error(message)
  process.exit(1)
}

const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'))
const version = String(pkg.version ?? '')

/** An iOS marketing version is up to three dot-separated integers: a prerelease
 *  suffix cannot be expressed in CFBundleShortVersionString, so the numeric part
 *  is what the bundle carries and package.json keeps the full version. */
const match = /^(\d+\.\d+\.\d+)/.exec(version)
if (!match) fail(`package.json version ${JSON.stringify(version)} is not of the form x.y.z`)
const marketing = match[1]
if (marketing !== version) {
  console.log(`note: iOS cannot carry ${JSON.stringify(version)}, the bundle gets ${marketing}`)
}

const body = `${HEADER.join('\n')}\nMARKETING_VERSION = ${marketing}\n`
const current = existsSync(TARGET) ? readFileSync(TARGET, 'utf8') : ''

if (process.argv.includes('--check')) {
  if (current !== body) fail('ios/version.xcconfig is out of date: run pnpm sync:version')
  console.log(`ios/version.xcconfig matches package.json (${marketing})`)
  process.exit(0)
}
if (current === body) {
  console.log(`ios/version.xcconfig already at ${marketing}`)
  process.exit(0)
}
writeFileSync(TARGET, body)
console.log(`ios/version.xcconfig -> MARKETING_VERSION = ${marketing}`)
